document.addEventListener("DOMContentLoaded",()=>{const dlg=document.getElementById("dwc-formula-dialog"),body=dlg.querySelector("tbody");const renumber=()=>Array.from(body.rows).forEach((r,i)=>r.querySelectorAll("input").forEach((x,j)=>x.name=(j===0?"dwc_threshold[":j===1?"dwc_points[":"condition_color[")+i+"]"));body.addEventListener("click",e=>{const r=e.target.closest("tr");if(!r)return;if(e.target.classList.contains("dwc-up")&&r.previousElementSibling)body.insertBefore(r,r.previousElementSibling);if(e.target.classList.contains("dwc-down")&&r.nextElementSibling)body.insertBefore(r.nextElementSibling,r);renumber()});const add=document.getElementById("dwc-add"),remove=document.getElementById("dwc-remove"),sort=document.getElementById("dwc-sort");if(add)add.onclick=()=>{if(body.rows.length>=40)return;const r=body.rows[body.rows.length-1].cloneNode(true);r.querySelectorAll("input").forEach((x,i)=>x.value=x.type==="color"?x.value:(i===1?0:Math.max(0,Number(x.value)-1)));body.appendChild(r);renumber();r.scrollIntoView({block:"nearest"})};if(remove)remove.onclick=()=>{if(body.rows.length>1)body.deleteRow(-1);renumber()};if(sort)sort.onclick=()=>{Array.from(body.rows).sort((a,b)=>Number(b.cells[0].querySelector("input").value)-Number(a.cells[0].querySelector("input").value)).forEach(r=>body.appendChild(r));renumber()};const form=dlg.querySelector("form");if(form)form.addEventListener("submit",renumber);dlg.querySelectorAll("input[type=color]").forEach(input=>input.addEventListener("input",()=>{const name=input.name.split("_")[1];const preview=dlg.querySelector(".metric-colour-preview span:nth-child("+({red:1,amber:2,green:3}[name])+")");if(preview)preview.style.background=input.value}))});
